CREATE TABLE IF NOT EXISTS "Quiz" ("id" UUID NOT NULL, "tenantId" UUID NOT NULL, "schoolId" UUID NOT NULL, "classroomId" UUID NOT NULL, "assignmentId" UUID, "assessmentWeightId" UUID, "authorId" UUID NOT NULL, "title" TEXT NOT NULL, "instructions" TEXT, "durationMinutes" INTEGER NOT NULL DEFAULT 30, "maxAttempts" INTEGER NOT NULL DEFAULT 1, "status" TEXT NOT NULL DEFAULT 'DRAFT', "publishedAt" TIMESTAMP(3), "closedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Quiz_pkey" PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "QuizQuestion" ("id" UUID NOT NULL, "quizId" UUID NOT NULL, "type" TEXT NOT NULL, "prompt" TEXT NOT NULL, "options" JSONB NOT NULL DEFAULT '[]', "correctAnswer" JSONB NOT NULL, "points" INTEGER NOT NULL DEFAULT 1, "position" INTEGER NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "QuizQuestion_pkey" PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "QuizAttempt" ("id" UUID NOT NULL, "tenantId" UUID NOT NULL, "schoolId" UUID NOT NULL, "quizId" UUID NOT NULL, "studentId" UUID NOT NULL, "attemptNumber" INTEGER NOT NULL, "status" TEXT NOT NULL DEFAULT 'IN_PROGRESS', "startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "expiresAt" TIMESTAMP(3) NOT NULL, "submittedAt" TIMESTAMP(3), "score" INTEGER, "maxScore" INTEGER, CONSTRAINT "QuizAttempt_pkey" PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "QuizAnswer" ("id" UUID NOT NULL, "attemptId" UUID NOT NULL, "questionId" UUID NOT NULL, "response" JSONB NOT NULL, "pointsAwarded" INTEGER, "answeredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "QuizAnswer_pkey" PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "Quiz_tenantId_schoolId_classroomId_status_createdAt_idx" ON "Quiz"("tenantId", "schoolId", "classroomId", "status", "createdAt");
CREATE UNIQUE INDEX IF NOT EXISTS "QuizQuestion_quizId_position_key" ON "QuizQuestion"("quizId", "position");
CREATE UNIQUE INDEX IF NOT EXISTS "QuizAttempt_quizId_studentId_attemptNumber_key" ON "QuizAttempt"("quizId", "studentId", "attemptNumber");
CREATE INDEX IF NOT EXISTS "QuizAttempt_tenantId_schoolId_studentId_status_idx" ON "QuizAttempt"("tenantId", "schoolId", "studentId", "status");
CREATE UNIQUE INDEX IF NOT EXISTS "QuizAnswer_attemptId_questionId_key" ON "QuizAnswer"("attemptId", "questionId");
DO $$ BEGIN ALTER TABLE "Quiz" ADD CONSTRAINT "Quiz_classroomId_fkey" FOREIGN KEY ("classroomId") REFERENCES "DigitalClassroom"("id") ON DELETE CASCADE ON UPDATE CASCADE; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN ALTER TABLE "Quiz" ADD CONSTRAINT "Quiz_assignmentId_fkey" FOREIGN KEY ("assignmentId") REFERENCES "Assignment"("id") ON DELETE SET NULL ON UPDATE CASCADE; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN ALTER TABLE "Quiz" ADD CONSTRAINT "Quiz_assessmentWeightId_fkey" FOREIGN KEY ("assessmentWeightId") REFERENCES "AssessmentWeight"("id") ON DELETE SET NULL ON UPDATE CASCADE; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN ALTER TABLE "Quiz" ADD CONSTRAINT "Quiz_authorId_fkey" FOREIGN KEY ("authorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN ALTER TABLE "QuizQuestion" ADD CONSTRAINT "QuizQuestion_quizId_fkey" FOREIGN KEY ("quizId") REFERENCES "Quiz"("id") ON DELETE CASCADE ON UPDATE CASCADE; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN ALTER TABLE "QuizAttempt" ADD CONSTRAINT "QuizAttempt_quizId_fkey" FOREIGN KEY ("quizId") REFERENCES "Quiz"("id") ON DELETE CASCADE ON UPDATE CASCADE; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN ALTER TABLE "QuizAttempt" ADD CONSTRAINT "QuizAttempt_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN ALTER TABLE "QuizAnswer" ADD CONSTRAINT "QuizAnswer_attemptId_fkey" FOREIGN KEY ("attemptId") REFERENCES "QuizAttempt"("id") ON DELETE CASCADE ON UPDATE CASCADE; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN ALTER TABLE "QuizAnswer" ADD CONSTRAINT "QuizAnswer_questionId_fkey" FOREIGN KEY ("questionId") REFERENCES "QuizQuestion"("id") ON DELETE CASCADE ON UPDATE CASCADE; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
